@namespace ghidra.features.@base.replace.items;



using ghidra.app.services;
using ghidra.features.@base.quickfix;
using ghidra.features.@base.replace;
using ghidra.framework.plugintool;
using ghidra.program.model.address;
using ghidra.program.model.data;
using ghidra.program.model.listing;
using ghidra.program.util;

/**
 * QuickFix for renaming datatypes.
 */
public class RenameDataTypeQuickFix : RenameQuickFix {

	private DataType dataType;

	/**
	 * Constructor
	 * @param program the program containing the datatype to be renamed
	 * @param dataType the datatype being renamed
	 * @param newName the new name for the datatype
	 */
	public RenameDataTypeQuickFix(Program program, DataType dataType, string newName) : base(program, dataType.getName(), newName)
    {
		this.dataType = dataType;
		if (!canRename()) {
			setStatus(QuickFixStatus.ERROR, "This datatype doesn't support renaming");
		}
		checkDuplicate();
	}

	private void checkDuplicate() {
		CategoryPath categoryPath = dataType.getCategoryPath();
		DataTypeManager dtm = dataType.getDataTypeManager();
		Category category = dtm.getCategory(categoryPath);
		DataType existing = category.getDataType(replacement);
		if (existing != null) {
			setStatus(QuickFixStatus.WARNING, "Datatype with name \"" + replacement +
				"\" already exists in category \"" + category.getCategoryPathName() + "\"");
		}
	}

	/* @Override */
	public string getItemType() {
		return "Datatype";
	}

	/* @Override */
	public Address getAddress() {
		return null;
	}

	private bool canRename() {
		return !(dataType is BuiltInDataType ||
			dataType is MissingBuiltInDataType || dataType is Array ||
			dataType is Pointer);
	}

	/* @Override */
	public string getPath() {
		return dataType.getCategoryPath().getPath();
	}

	/* @Override */
	public string doGetCurrent() {
		if (dataType.isDeleted()) {
			return null;
		}
		return dataType.getName();
	}

	/* @Override */
	public void execute() {
		try {
			dataType.setName(replacement);
		}
		catch (Exception e) {
			setStatus(QuickFixStatus.ERROR, "Rename datatype failed: " + e.getMessage());
		}
	}

	/* @Override */
	public ProgramLocation getProgramLocation() {
		return null;
	}

	/* @Override */
	protected bool navigateSpecial(ServiceProvider services, bool fromSelectionChange) {
		DataTypeManagerService dtmService = services.getService(typeof(DataTypeManagerService));
		if (dtmService == null) {
			return false;
		}

		dtmService.setDataTypeSelected(dataType);

		if (!fromSelectionChange) {
			dtmService.edit(dataType);
		}
		return true;
	}

	/* @Override */
	public Map<string, string> getCustomToolTipData() {
		return Map.of("Category", dataType.getCategoryPath().toString());
	}
}
